content.text:
Brief:
Un long cahier des charges pour un jeu de phare en plusieurs niveaux. Le joueur est le gardien d'un vieux phare sur une côte rocheuse, et chaque niveau se passe pendant une nuit de tempête. Des bateaux approchent depuis le large, et le joueur doit tourner le faisceau du phare en glissant le doigt autour de la tour pour éclairer chaque bateau avant qu'il ne touche les rochers. Un bateau éclairé assez longtemps trouve le chenal et rentre au port, ce qui compte pour l'objectif du niveau. Quand tous les bateaux d'une nuit sont rentrés, le niveau est gagné et une courte carte annonce la nuit suivante. Les nuits suivantes amènent plus de bateaux, du brouillard qui cache une partie de la mer et des vagues qui déplacent les bateaux. Si un bateau touche les rochers, la partie est perdue, avec un message qui dit quel bateau a coulé et un bouton pour rejouer la nuit. Je voudrais une mer bleu nuit, un faisceau jaune pâle et des bateaux rouges, dessinés simplement avec des formes plates. Le texte du jeu doit rester en français, avec le numéro de la nuit affiché en haut de l'écran pendant toute la partie.

Plan:
{"gameType":"stage-clear","input":"drag-follow","lang":"fr","loop":"Faites glisser le doigt autour de la tour pour tourner le faisceau et éclairer chaque bateau assez longtemps pour qu'il rentre au port. Guidez tous les bateaux de la nuit pour gagner ; un bateau qui touche les rochers fait perdre la nuit.","slug":"le-gardien-du-phare","style":"paper-cut","title":"Le Gardien du Phare"}

Game source (line-numbered):
1| <!doctype html>
2| <html lang="fr">
3| <head>
4| <meta charset="utf-8">
5| <meta name="viewport" content="width=device-width, initial-scale=1">
6| <title>Le Gardien du Phare</title>
7| <style>
8|   html, body {
9|     margin: 0; padding: 0; width: 100%; height: 100%;
10|     background: #f4ecd8;
11|     overflow: hidden;
12|     font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
13|     touch-action: none;
14|   }
15|   canvas {
16|     display: block;
17|     width: 100vw;
18|     height: 100dvh;
19|   }
20| </style>
21| </head>
22| <body>
23| <canvas id="game"></canvas>
24| <script>
25| // ---- Bridge helper (verbatim) ----
26| const CARTRIDGE = {
27|   send(type, payload = {}) {
28|     window.parent.postMessage(
29|       { source: "cartridge", v: 1, type, payload },
30|       "*",
31|     );
32|   },
33| };
34| 
35| window.addEventListener("message", (event) => {
36|   const data = event.data;
37|   if (!data || data.source !== "cartridge-host") return;
38|   if (data.type === "pause") paused = true;
39|   if (data.type === "resume") paused = false;
40|   if (data.type === "reset") backToTitle();
41| });
42| </script>
43| <script>
44| (function(){
45|   const canvas = document.getElementById("game");
46|   const ctx = canvas.getContext("2d");
47| 
48|   // ---- Palette ----
49|   const COLORS = {
50|     bg: "#f4ecd8",
51|     layer: "#e07a5f",
52|     accent: "#3d405b",
53|     highlight: "#81b29a"
54|   };
55| 
56|   // ---- Sizing ----
57|   let W = 0, H = 0, DPR = 1;
58|   function resize() {
59|     DPR = window.devicePixelRatio || 1;
60|     W = window.innerWidth;
61|     H = window.innerHeight;
62|     canvas.width = Math.round(W * DPR);
63|     canvas.height = Math.round(H * DPR);
64|     ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
65|   }
66|   window.addEventListener("resize", resize);
67|   resize();
68| 
69|   // ---- Seeded jitter for paper-cut edges ----
70|   function mulberry32(a) {
71|     return function() {
72|       a |= 0; a = (a + 0x6D2B79F5) | 0;
73|       let t = Math.imul(a ^ (a >>> 15), 1 | a);
74|       t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
75|       return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
76|     };
77|   }
78|   const rng = mulberry32(1337);
79|   function jitter(amount) { return (rng() - 0.5) * 2 * amount; }
80| 
81|   // Precompute jittered polygon points once per shape id, cached
82|   const jitterCache = {};
83|   function jitteredPoly(id, points, amt) {
84|     if (jitterCache[id]) return jitterCache[id];
85|     const out = points.map(p => [p[0] + jitter(amt), p[1] + jitter(amt)]);
86|     jitterCache[id] = out;
87|     return out;
88|   }
89| 
90|   function drawPaperShadow(fn) {
91|     ctx.save();
92|     ctx.shadowColor = "rgba(61,64,91,0.35)";
93|     ctx.shadowBlur = 6;
94|     ctx.shadowOffsetY = 3;
95|     fn();
96|     ctx.restore();
97|   }
98| 
99|   function roundRectPath(x, y, w, h, r) {
100|     ctx.beginPath();
101|     ctx.moveTo(x + r, y);
102|     ctx.arcTo(x + w, y, x + w, y + h, r);
103|     ctx.arcTo(x + w, y + h, x, y + h, r);
104|     ctx.arcTo(x, y + h, x, y, r);
105|     ctx.arcTo(x, y, x + w, y, r);
106|     ctx.closePath();
107|   }
108| 
109|   // ---- Game state ----
110|   const STAGES = [
111|     { goal: 1, boats: 1, speed: 0.55, rockDanger: 1 },
112|     { goal: 2, boats: 2, speed: 0.65, rockDanger: 1 },
113|     { goal: 3, boats: 3, speed: 0.75, rockDanger: 1.2 },
114|     { goal: 4, boats: 4, speed: 0.85, rockDanger: 1.3 },
115|     { goal: 5, boats: 5, speed: 0.95, rockDanger: 1.5 }
116|   ];
117| 
118|   let stage = 0;
119|   let screenState = "title"; // title, grace, playing, stagewin, win, lose
120|   let paused = false;
121|   let booted = false;
122|   let started = false;
123| 
124|   let beamAngle = 0; // radians
125|   let targetAngle = 0;
126|   let center = { x: 0, y: 0 };
127|   let towerRadius = 60;
128|   let rocksAngle = []; // list of rock angle ranges (rad)
129|   let boats = [];
130|   let savedCount = 0;
131|   let goalCount = 1;
132|   let graceTimer = 0;
133|   let stageMessage = "";
134|   let stageMessageTimer = 0;
135|   let elapsed = 0;
136| 
137|   function backToTitle() {
138|     screenState = "title";
139|     started = false;
140|     stage = 0;
141|     savedCount = 0;
142|   }
143| 
144|   function angleDiff(a, b) {
145|     let d = (a - b) % (Math.PI * 2);
146|     if (d > Math.PI) d -= Math.PI * 2;
147|     if (d < -Math.PI) d += Math.PI * 2;
148|     return d;
149|   }
150| 
151|   function buildStage(n) {
152|     const cfg = STAGES[n - 1];
153|     goalCount = cfg.goal;
154|     savedCount = 0;
155|     boats = [];
156|     // rocks: 2-3 fixed danger arcs around the tower
157|     rocksAngle = [];
158|     const rockCount = 2 + (n > 2 ? 1 : 0);
159|     for (let i = 0; i < rockCount; i++) {
160|       const a = (Math.PI * 2 / rockCount) * i + jitter(0.3);
161|       rocksAngle.push({ center: a, width: 0.35 * cfg.rockDanger });
162|     }
163|     for (let i = 0; i < cfg.boats; i++) {
164|       spawnBoat(cfg.speed, i * 1.3);
165|     }
166|     stageMessage = "Phare " + n + " : guidez " + cfg.goal + " bateau" + (cfg.goal > 1 ? "x" : "") + " au port";
167|     stageMessageTimer = 3.5;
168|     graceTimer = 3.0; // grace period before rocks can sink boats
169|     screenState = "grace";
170|     elapsed = 0;
171|     CARTRIDGE.send("level", { index: n });
172|   }
173| 
174|   function spawnBoat(speed, delayOffset) {
175|     const startAngle = rng() * Math.PI * 2;
176|     const dir = rng() < 0.5 ? 1 : -1;
177|     boats.push({
178|       angle: startAngle,
179|       dist: 1.0, // 1 = far, 0 = at port (center ring)
180|       speed: speed * (0.85 + rng() * 0.3),
181|       dir,
182|       lit: 0, // how long continuously lit
183|       needLit: 1.6, // seconds of light needed to guide safely inward
184|       saved: false,
185|       sunk: false,
186|       wobble: rng() * 10,
187|       delay: delayOffset
188|     });
189|   }
190| 
191|   function enterStage(next) {
192|     stage = next;
193|     buildStage(stage);
194|   }
195| 
196|   function onGoalMet() {
197|     if (stage === STAGES.length) {
198|       screenState = "win";
199|       CARTRIDGE.send("end", { reason: "win" });
200|     } else {
201|       screenState = "stagewin";
202|       stageMessageTimer = 1.8;
203|     }
204|   }
205| 
206|   function onStageFailed() {
207|     screenState = "lose";
208|     CARTRIDGE.send("end", { reason: "lose" });
209|   }
210| 
211|   // ---- Input: drag to rotate beam ----
212|   function toCanvas(evt) {
213|     const rect = canvas.getBoundingClientRect();
214|     return {
215|       x: (evt.clientX - rect.left),
216|       y: (evt.clientY - rect.top)
217|     };
218|   }
219| 
220|   let held = false;
221| 
222|   canvas.addEventListener("pointerdown", (event) => {
223|     const p = toCanvas(event);
224|     if (screenState === "title") {
225|       startGame();
226|       return;
227|     }
228|     if (screenState === "stagewin" || screenState === "win" || screenState === "lose") {
229|       return;
230|     }
231|     held = true;
232|     canvas.setPointerCapture(event.pointerId);
233|     updateTargetFromPoint(p);
234|   });
235|   canvas.addEventListener("pointermove", (event) => {
236|     if (!held) return;
237|     updateTargetFromPoint(toCanvas(event));
238|   });
239|   canvas.addEventListener("pointerup", () => { held = false; });
240|   canvas.addEventListener("pointercancel", () => { held = false; });
241| 
242|   function updateTargetFromPoint(p) {
243|     const dx = p.x - center.x;
244|     const dy = p.y - center.y;
245|     targetAngle = Math.atan2(dy, dx);
246|   }
247| 
248|   function startGame() {
249|     started = true;
250|     CARTRIDGE.send("start");
251|     enterStage(1);
252|   }
253| 
254|   // ---- Update ----
255|   function update(dt) {
256|     if (paused) return;
257|     center.x = W / 2;
258|     center.y = H / 2;
259| 
260|     if (screenState === "title" || screenState === "win" || screenState === "lose") {
261|       // idle animation of the beam
262|       targetAngle += dt * 0.15;
263|     }
264| 
265|     // ease beam angle towards target
266|     let diff = angleDiff(targetAngle, beamAngle);
267|     beamAngle += diff * Math.min(1, dt * 6);
268| 
269|     if (stageMessageTimer > 0) stageMessageTimer -= dt;
270| 
271|     if (screenState === "grace") {
272|       graceTimer -= dt;
273|       updateBoats(dt, false);
274|       if (graceTimer <= 0) screenState = "playing";
275|       return;
276|     }
277| 
278|     if (screenState === "playing") {
279|       elapsed += dt;
280|       updateBoats(dt, true);
281|     }
282| 
283|     if (screenState === "stagewin") {
284|       if (stageMessageTimer <= 0) {
285|         enterStage(stage + 1);
286|       }
287|     }
288|   }
289| 
290|   const beamHalfWidth = 0.24; // radians of beam cone
291| 
292|   function isLit(boat) {
293|     const d = Math.abs(angleDiff(beamAngle, boat.angle));
294|     return d < beamHalfWidth;
295|   }
296| 
297|   function inRockZone(angle) {
298|     for (const r of rocksAngle) {
299|       const d = Math.abs(angleDiff(angle, r.center));
300|       if (d < r.width) return true;
301|     }
302|     return false;
303|   }
304| 
305|   function updateBoats(dt, dangerActive) {
306|     for (const boat of boats) {
307|       if (boat.saved || boat.sunk) continue;
308|       boat.wobble += dt * 3;
309| 
310|       if (isLit(boat)) {
311|         boat.lit += dt;
312|       } else {
313|         boat.lit = Math.max(0, boat.lit - dt * 0.5);
314|       }
315| 
316|       // boat drifts slowly around the tower
317|       boat.angle += boat.dir * dt * 0.12;
318| 
319|       // move inward only if sufficiently lit
320|       if (boat.lit >= boat.needLit) {
321|         boat.dist -= dt * boat.speed * 0.18;
322|       } else {
323|         // drifts outward slowly if neglected too long
324|         boat.dist += dt * 0.02;
325|         if (boat.dist > 1.15) boat.dist = 1.15;
326|       }
327| 
328|       if (boat.dist <= 0.18) {
329|         boat.saved = true;
330|         savedCount++;
331|         if (savedCount >= goalCount) {
332|           onGoalMet();
333|         }
334|         continue;
335|       }
336| 
337|       // danger: if boat is within rock zone distance band and not lit enough
338|       if (dangerActive) {
339|         const dangerBand = boat.dist < 0.75 && boat.dist > 0.25;
340|         if (dangerBand && inRockZone(boat.angle) && boat.lit < 0.5) {
341|           boat.sunk = true;
342|           onStageFailed();
343|         }
344|       }
345|     }
346|   }
347| 
348|   // ---- Drawing ----
349|   function drawBackground() {
350|     ctx.fillStyle = COLORS.bg;
351|     ctx.fillRect(0, 0, W, H);
352|     // subtle paper texture lines (cut layers)
353|     ctx.save();
354|     ctx.globalAlpha = 0.05;
355|     ctx.strokeStyle = COLORS.accent;
356|     for (let i = 0; i < 6; i++) {
357|       ctx.beginPath();
358|       ctx.moveTo(0, (H / 6) * i);
359|       ctx.lineTo(W, (H / 6) * i + 20);
360|       ctx.stroke();
361|     }
362|     ctx.restore();
363|   }
364| 
365|   function drawSea() {
366|     const R = Math.min(W, H) * 0.42;
367|     drawPaperShadow(() => {
368|       ctx.fillStyle = COLORS.highlight;
369|       ctx.beginPath();
370|       ctx.arc(center.x, center.y, R, 0, Math.PI * 2);
371|       ctx.fill();
372|     });
373|   }
374| 
375|   function drawRocks() {
376|     const R = Math.min(W, H) * 0.42;
377|     for (let i = 0; i < rocksAngle.length; i++) {
378|       const r = rocksAngle[i];
379|       ctx.save();
380|       ctx.translate(center.x, center.y);
381|       ctx.rotate(r.center);
382|       drawPaperShadow(() => {
383|         ctx.fillStyle = COLORS.accent;
384|         ctx.beginPath();
385|         const rockDist = R * 0.72;
386|         const pts = jitteredPoly("rock" + i, [
387|           [rockDist - 14, -16],
388|           [rockDist + 14, -10],
389|           [rockDist + 18, 8],
390|           [rockDist - 6, 18],
391|           [rockDist - 20, 2]
392|         ], 2);
393|         ctx.moveTo(pts[0][0], pts[0][1]);
394|         for (let k = 1; k < pts.length; k++) ctx.lineTo(pts[k][0], pts[k][1]);
395|         ctx.closePath();
396|         ctx.fill();
397|       });
398|       ctx.restore();
399|     }
400|   }
401| 
402|   function drawPort() {
403|     drawPaperShadow(() => {
404|       ctx.fillStyle = "#c9b183";
405|       ctx.beginPath();
406|       ctx.arc(center.x, center.y, towerRadius * 0.6, 0, Math.PI * 2);
407|       ctx.fill();
408|     });
409|   }
410| 
411|   function drawTower() {
412|     drawPaperShadow(() => {
413|       ctx.fillStyle = COLORS.layer;
414|       roundRectPath(center.x - towerRadius * 0.35, center.y - towerRadius, towerRadius * 0.7, towerRadius * 2, 10);
415|       ctx.fill();
416|     });
417|     // lamp housing
418|     ctx.save();
419|     ctx.translate(center.x, center.y);
420|     ctx.rotate(beamAngle);
421|     drawPaperShadow(() => {
422|       ctx.fillStyle = COLORS.accent;
423|       roundRectPath(0, -12, 34, 24, 8);
424|       ctx.fill();
425|     });
426|     ctx.restore();
427|   }
428| 
429|   function drawBeam() {
430|     const R = Math.min(W, H) * 0.48;
431|     ctx.save();
432|     ctx.translate(center.x, center.y);
433|     const grad = ctx.createRadialGradient(0, 0, 5, 0, 0, R);
434|     grad.addColorStop(0, "rgba(244,236,216,0.65)");
435|     grad.addColorStop(1, "rgba(244,236,216,0)");
436|     ctx.fillStyle = grad;
437|     ctx.beginPath();
438|     ctx.moveTo(0, 0);
439|     ctx.arc(0, 0, R, beamAngle - beamHalfWidth, beamAngle + beamHalfWidth);
440|     ctx.closePath();
441|     ctx.fill();
442|     ctx.restore();
443|   }
444| 
445|   function drawBoat(boat) {
446|     const R = Math.min(W, H) * 0.42;
447|     const dist = 30 + boat.dist * (R - 30);
448|     const x = center.x + Math.cos(boat.angle) * dist;
449|     const y = center.y + Math.sin(boat.angle) * dist + Math.sin(boat.wobble) * 2;
450|     const lit = isLit(boat);
451| 
452|     ctx.save();
453|     ctx.translate(x, y);
454|     ctx.rotate(boat.angle + Math.PI / 2);
455|     drawPaperShadow(() => {
456|       ctx.fillStyle = lit ? COLORS.highlight : COLORS.accent;
457|       ctx.beginPath();
458|       const pts = jitteredPoly("boat" + boats.indexOf(boat), [
459|         [0, -12],
460|         [8, 6],
461|         [0, 10],
462|         [-8, 6]
463|       ], 1.5);
464|       ctx.moveTo(pts[0][0], pts[0][1]);
465|       for (let k = 1; k < pts.length; k++) ctx.lineTo(pts[k][0], pts[k][1]);
466|       ctx.closePath();
467|       ctx.fill();
468|     });
469|     ctx.restore();
470| 
471|     // lit progress ring
472|     if (lit && !boat.saved) {
473|       ctx.save();
474|       ctx.strokeStyle = COLORS.layer;
475|       ctx.lineWidth = 3;
476|       ctx.beginPath();
477|       const frac = Math.min(1, boat.lit / boat.needLit);
478|       ctx.arc(x, y, 16, -Math.PI / 2, -Math.PI / 2 + frac * Math.PI * 2);
479|       ctx.stroke();
480|       ctx.restore();
481|     }
482|   }
483| 
484|   function drawBoats() {
485|     for (const boat of boats) {
486|       if (boat.saved || boat.sunk) continue;
487|       drawBoat(boat);
488|     }
489|   }
490| 
491|   function drawCard(text, subtext, y) {
492|     ctx.save();
493|     ctx.font = "bold 26px sans-serif";
494|     const w = Math.max(260, ctx.measureText(text).width + 60);
495|     const h = subtext ? 110 : 70;
496|     const x = center.x - w / 2;
497|     const yy = y - h / 2;
498|     drawPaperShadow(() => {
499|       ctx.fillStyle = "#fffaf0";
500|       roundRectPath(x, yy, w, h, 14);
501|       ctx.fill();
502|     });
503|     ctx.fillStyle = COLORS.accent;
504|     ctx.textAlign = "center";
505|     ctx.textBaseline = "middle";
506|     ctx.fillText(text, center.x, yy + (subtext ? 38 : h / 2));
507|     if (subtext) {
508|       ctx.font = "16px sans-serif";
509|       ctx.fillText(subtext, center.x, yy + 78);
510|     }
511|     ctx.restore();
512|   }
513| 
514|   function drawHUD() {
515|     ctx.save();
516|     ctx.font = "bold 18px sans-serif";
517|     ctx.fillStyle = COLORS.accent;
518|     ctx.textAlign = "left";
519|     ctx.textBaseline = "top";
520|     ctx.fillText("Phare " + stage + "  •  Sauvés: " + savedCount + "/" + goalCount, 16, 16);
521|     ctx.restore();
522|   }
523| 
524|   function render() {
525|     towerRadius = Math.min(W, H) * 0.09;
526|     drawBackground();
527|     drawSea();
528|     drawRocks();
529|     drawBeam();
530|     drawBoats();
531|     drawTower();
532|     drawPort();
533| 
534|     if (screenState === "title") {
535|       drawCard("Le Gardien du Phare", "Touchez et glissez pour tourner le faisceau", center.y);
536|     } else if (screenState === "grace" || screenState === "playing") {
537|       drawHUD();
538|       if (stageMessageTimer > 0) {
539|         drawCard(stageMessage, null, 90);
540|       }
541|       if (screenState === "grace") {
542|         ctx.save();
543|         ctx.font = "bold 16px sans-serif";
544|         ctx.fillStyle = COLORS.accent;
545|         ctx.textAlign = "center";
546|         ctx.fillText("Préparez-vous...", center.x, H - 40);
547|         ctx.restore();
548|       }
549|     } else if (screenState === "stagewin") {
550|       drawHUD();
551|       drawCard("Phare " + stage + " terminé !", "Prochain phare...", center.y);
552|     } else if (screenState === "win") {
553|       drawCard("Toutes les nuits sont sauves !", "Vous avez gagné", center.y);
554|     } else if (screenState === "lose") {
555|       drawCard("Un bateau a heurté les rochers...", "Nuit perdue", center.y);
556|     }
557| 
558|     if (paused && (screenState === "grace" || screenState === "playing")) {
559|       ctx.save();
560|       ctx.fillStyle = "rgba(61,64,91,0.4)";
561|       ctx.fillRect(0, 0, W, H);
562|       ctx.restore();
563|       drawCard("Pause", null, center.y);
564|     }
565|   }
566| 
567|   // ---- Main loop ----
568|   let lastTime = null;
569|   function frame(ts) {
570|     if (lastTime === null) lastTime = ts;
571|     let dt = (ts - lastTime) / 1000;
572|     lastTime = ts;
573|     if (dt > 0.1) dt = 0.1;
574| 
575|     update(dt);
576|     render();
577| 
578|     if (!booted) {
579|       booted = true;
580|       CARTRIDGE.send("boot", { title: "Le Gardien du Phare", gameType: "stage-clear", lang: "fr" });
581|     }
582| 
583|     requestAnimationFrame(frame);
584|   }
585| 
586|   center.x = window.innerWidth / 2;
587|   center.y = window.innerHeight / 2;
588|   targetAngle = 0;
589|   requestAnimationFrame(frame);
590| })();
591| </script>
592| </body>
593| </html>
594|

